                        "Cume axsami", "Cume", "Senbe", "Bazar"};

    // k dəyəri 1-7 arasındadır, massivin indeksi isə 0-6 — ona görə k-dan 1 çıxırıq.
    cout << names[k - 1] << "\n";
}

