    // 0 üçün heç işləməzdi (çünki n>0 şərti dərhal yalan olardı) — ona görə
    // bunu əvvəlcədən ayrıca yoxlayırıq.
    if (n == 0) {
        cout << 1 << "\n";
        return 0;
    }

    int cnt = 0;
    // Hər addımda n-i 10-a bölərək bir rəqəmi "atırıq" və sayğacı artırırıq —
